document.addEventListener("DOMContentLoaded",init);async function init(){const owner=await Auth.guardOwnerAuth();if(!owner)return;if(!owner.isAdmin){document.getElementById("admin-denied").classList.remove("hidden");return}document.getElementById("admin-tools").classList.remove("hidden");await loadStores();document.getElementById("feature-store-btn").addEventListener("click",onFeatureStore);document.getElementById("prod-store-select").addEventListener("change",onPickStoreForProduct);document.getElementById("feature-product-btn").addEventListener("click",onFeatureProduct);document.getElementById("badge-recompute-btn").addEventListener("click",onRecomputeBadges);loadFeatured();loadSellerBadges();loadWholesalers();loadFeaturePayments();initAdminSearch()}async function loadStores(){const res=await Api.get("listStores",{});const stores=res.ok?res.stores||[]:[];const opts=['<option value="">Choose a store…</option>'].concat(stores.map(s=>`<option value="${escapeHtml(s.storeSlug)}">${escapeHtml(s.storeName)}</option>`)).join("");document.getElementById("store-select").innerHTML=opts;document.getElementById("prod-store-select").innerHTML=opts}async function onPickStoreForProduct(){const slug=document.getElementById("prod-store-select").value;const sel=document.getElementById("product-select");if(!slug){sel.innerHTML='<option value="">Choose a store first…</option>';return}sel.innerHTML='<option value="">Loading…</option>';const res=await Api.get("listProducts",{storeSlug:slug});const products=res.ok?res.products||[]:[];sel.innerHTML=['<option value="">Choose a product…</option>'].concat(products.map(p=>`<option value="${escapeHtml(p.productId)}">${escapeHtml(p.name)}</option>`)).join("")}function onFeatureStore(){const slug=document.getElementById("store-select").value;if(slug)addFeatured("store",slug)}function onFeatureProduct(){const pid=document.getElementById("product-select").value;if(pid)addFeatured("product",pid)}async function addFeatured(type,refId){const errorEl=document.getElementById("admin-error");errorEl.textContent="";const res=await Api.post("addFeatured",{token:Auth.getToken(),type:type,refId:refId});if(!res.ok){errorEl.textContent=res.error||"Could not add that item.";return}loadFeatured()}async function loadFeatured(){const statusEl=document.getElementById("featured-status");const listEl=document.getElementById("featured-list");const stop=startLoadingMessage(statusEl);const res=await Api.post("listFeatured",{token:Auth.getToken()});stop();if(!res.ok){listEl.innerHTML="";showLoadFailedMessage(statusEl);return}const items=res.featured||[];if(items.length===0){listEl.innerHTML="";statusEl.textContent="Nothing featured yet.";return}statusEl.textContent="";listEl.innerHTML=items.map(featuredRow).join("");listEl.querySelectorAll("[data-remove]").forEach(btn=>{btn.addEventListener("click",()=>onRemove(btn.dataset.remove))})}function featuredRow(f){return`\n    <div class="dash-item">\n      <div class="dash-item-main">\n        <strong>${escapeHtml(f.label)}</strong>\n        <span class="helper-text">${escapeHtml(f.type)}</span>\n      </div>\n      <div class="dash-item-side">\n        <button type="button" class="btn btn-small btn-danger" data-remove="${escapeHtml(f.featuredId)}">Remove</button>\n      </div>\n    </div>`}async function onRemove(featuredId){const res=await Api.post("removeFeatured",{token:Auth.getToken(),featuredId:featuredId});if(res.ok)loadFeatured()}let badgeSellers=[];let badgeConfigValues={};async function loadSellerBadges(){const statusEl=document.getElementById("badge-status");const listEl=document.getElementById("badge-seller-list");const stop=startLoadingMessage(statusEl);const res=await Api.post("listSellerBadges",{token:Auth.getToken()});stop();if(!res.ok){listEl.innerHTML="";showLoadFailedMessage(statusEl);return}badgeSellers=res.sellers||[];badgeConfigValues=res.config||{};statusEl.textContent=badgeSellers.length?"":"No stores yet.";const stamped=badgeSellers.map(s=>s.updatedAt).filter(Boolean).sort();document.getElementById("badge-updated").textContent=stamped.length?"Last worked out "+new Date(stamped[stamped.length-1]).toLocaleString():"Not worked out yet — press Recompute now.";listEl.innerHTML=badgeSellers.map(sellerBadgeRowHtml).join("");wireSellerBadgeControls();renderBadgeConfig()}function sellerBadgeRowHtml(s){const chip=ids=>typeof renderSellerBadges==="function"?renderSellerBadges(ids,{size:"chip",interactive:false}):"";const shown=s.badges.length?s.badges.map(id=>`\n        <div class="badge-admin-item">\n          ${chip([id])}\n          <span class="badge-admin-source badge-admin-source--${s.source[id]==="admin"?"admin":"auto"}">\n            ${s.source[id]==="admin"?"ADMIN OVERRIDE":"AUTO AWARDED"}\n          </span>\n          ${s.why[id]?`<span class="helper-text badge-admin-why">${escapeHtml(s.why[id])}</span>`:""}\n        </div>`).join(""):'<p class="helper-text">No badges.</p>';const withheld=(s.autoBadges||[]).filter(id=>s.badges.indexOf(id)===-1);const withheldHtml=withheld.length?`<div class="badge-admin-item badge-admin-item--withheld">\n         ${chip(withheld)}\n         <span class="badge-admin-source badge-admin-source--withheld">EARNED, NOT SHOWN</span>\n         <span class="helper-text badge-admin-why">${s.suppressed?"This store is hidden from all badges.":"Removed by an admin."}</span>\n       </div>`:"";const m=s.metrics||{};const figure=(label,value)=>`<span><strong>${escapeHtml(String(value))}</strong> ${label}</span>`;return`\n    <div class="dash-item badge-admin-row" data-owner-id="${escapeHtml(s.ownerId)}">\n      <div class="badge-admin-head">\n        <strong>${escapeHtml(s.storeName||s.storeSlug)}</strong>\n        <span class="helper-text">${escapeHtml(s.storeSlug)}${s.status&&s.status!=="active"?" · "+escapeHtml(s.status):""}</span>\n      </div>\n\n      <p class="helper-text badge-admin-figures">\n        ${s.score===null?"<span>Not enough data to score</span>":figure("score",s.score)}\n        ${figure("orders",m.orders||0)}\n        ${figure("fulfilled",m.fulfilled||0)}\n        ${figure("cancelled",m.cancelled||0)}\n        ${figure("reviews",m.reviews||0)}\n        ${m.rating!=null?figure("average",m.rating):""}\n        ${m.medianReplyMinutes!=null?figure("min median reply",m.medianReplyMinutes):""}\n        ${figure("repeat customers",m.repeatCustomers||0)}\n      </p>\n\n      <div class="badge-admin-badges">${shown}${withheldHtml}</div>\n\n      <div class="badge-admin-controls">\n        ${overrideControl(s,"verified","Verified Seller")}\n        ${overrideControl(s,"recommended","Mwakete Recommended")}\n        <label class="badge-admin-suppress">\n          <input type="checkbox" data-badge-suppress ${s.suppressed?"checked":""}>\n          Hide all badges for this store\n        </label>\n      </div>\n    </div>`}function overrideControl(s,field,label){const current=s.overrides[field]||"";const opt=(v,text)=>`<option value="${v}"${current===v?" selected":""}>${text}</option>`;return`\n    <label class="badge-admin-override">\n      <span>${escapeHtml(label)}</span>\n      <select data-badge-field="${field}">\n        ${opt("","Automatic")}\n        ${opt("true","Granted")}\n        ${opt("false","Removed")}\n      </select>\n    </label>`}function wireSellerBadgeControls(){document.querySelectorAll(".badge-admin-row").forEach(row=>{const ownerId=row.dataset.ownerId;row.querySelectorAll("[data-badge-field]").forEach(sel=>{sel.addEventListener("change",()=>setBadgeOverride(ownerId,sel.dataset.badgeField,sel.value,sel))});const box=row.querySelector("[data-badge-suppress]");if(box){box.addEventListener("change",()=>setBadgeOverride(ownerId,"suppressed",box.checked?"true":"",box))}})}async function setBadgeOverride(ownerId,field,value,control){const errorEl=document.getElementById("badge-error");errorEl.textContent="";control.disabled=true;const res=await Api.post("setSellerBadgeOverride",{token:Auth.getToken(),ownerId:ownerId,field:field,value:value});control.disabled=false;if(!res.ok){errorEl.textContent=res.error||"Could not change that.";return}loadSellerBadges()}function renderBadgeConfig(){const el=document.getElementById("badge-config-list");if(!el)return;const keys=Object.keys(badgeConfigValues).sort();el.innerHTML=keys.map(key=>{const value=badgeConfigValues[key];const isFlag=value==="true"||value==="false";const id="cfg-"+key.replace(/[^a-z0-9]/gi,"-");const input=isFlag?`<select id="${id}" data-config-key="${escapeHtml(key)}">\n           <option value="true"${value==="true"?" selected":""}>On</option>\n           <option value="false"${value==="false"?" selected":""}>Off</option>\n         </select>`:`<input id="${id}" type="number" step="any" min="0"\n           data-config-key="${escapeHtml(key)}" value="${escapeHtml(String(value))}">`;return`<div class="field badge-config-field">\n        <label for="${id}">${escapeHtml(key)}</label>\n        ${input}\n      </div>`}).join("");el.querySelectorAll("[data-config-key]").forEach(input=>{input.addEventListener("change",()=>saveBadgeConfig(input))})}async function saveBadgeConfig(input){const errorEl=document.getElementById("badge-error");errorEl.textContent="";input.disabled=true;const res=await Api.post("setBadgeConfig",{token:Auth.getToken(),key:input.dataset.configKey,value:input.value});input.disabled=false;if(!res.ok){errorEl.textContent=res.error||"Could not save that setting.";return}loadSellerBadges()}async function onRecomputeBadges(){const btn=document.getElementById("badge-recompute-btn");const errorEl=document.getElementById("badge-error");errorEl.textContent="";btn.disabled=true;btn.textContent="Working…";const res=await Api.post("recomputeBadges",{token:Auth.getToken()});btn.disabled=false;btn.textContent="Recompute now";if(!res.ok){errorEl.textContent=res.error||"Could not recompute.";return}loadSellerBadges()}async function loadWholesalers(){const statusEl=document.getElementById("wholesale-status");const listEl=document.getElementById("wholesale-list");const stop=startLoadingMessage(statusEl);const res=await Api.post("listWholesalers",{token:Auth.getToken()});stop();if(!res.ok){listEl.innerHTML="";showLoadFailedMessage(statusEl);return}const list=res.wholesalers||[];statusEl.textContent=list.length?"":"No wholesaler stores yet.";listEl.innerHTML=list.map(wholesalerRowHtml).join("");listEl.querySelectorAll("[data-verify]").forEach(btn=>{btn.addEventListener("click",()=>setWholesaleVerified(btn.dataset.ownerId,btn.dataset.verify==="true",btn))})}function wholesalerRowHtml(w){const joined=w.createdAt?new Date(w.createdAt).toLocaleDateString():"";const phoneHref=String(w.phone||"").replace(/[^0-9+]/g,"");return`\n    <div class="wholesale-row${w.verified?" is-verified":""}">\n      <div class="wholesale-row-info">\n        <strong>${escapeHtml(w.storeName)}</strong>\n        ${w.storeType==="distributor"?'<span class="helper-text">Distributor</span>':""}\n        <span class="status-badge ${w.verified?"status-active":"status-hidden"}">${w.verified?"Verified":"Call pending"}</span>\n        <div class="helper-text">\n          ${w.phone?`<a href="tel:${escapeAttr(phoneHref)}">${escapeHtml(w.phone)}</a> · `:""}${escapeHtml(w.email||"")}${joined?" · joined "+escapeHtml(joined):""}\n        </div>\n      </div>\n      <button type="button" class="btn btn-small${w.verified?"":" btn-primary"}" data-owner-id="${escapeAttr(w.ownerId)}" data-verify="${w.verified?"false":"true"}">\n        ${w.verified?"Undo verification":"Mark Verified"}\n      </button>\n    </div>\n  `}async function setWholesaleVerified(ownerId,verified,btn){const errorEl=document.getElementById("wholesale-error");errorEl.textContent="";btn.disabled=true;const res=await Api.post("setWholesaleVerified",{token:Auth.getToken(),ownerId:ownerId,verified:verified});if(!res.ok){btn.disabled=false;errorEl.textContent=res.error||"Could not update that store.";return}await loadWholesalers()}async function loadFeaturePayments(){const statusEl=document.getElementById("feature-payments-status");const listEl=document.getElementById("feature-payments-list");const stop=startLoadingMessage(statusEl);const res=await Api.post("listFeaturePurchases",{token:Auth.getToken()});stop();if(!res.ok){listEl.innerHTML="";showLoadFailedMessage(statusEl);return}const list=res.purchases||[];statusEl.textContent=list.length?"":"No featuring payments yet.";listEl.innerHTML=list.map(featurePaymentRowHtml).join("");listEl.querySelectorAll("[data-approve]").forEach(btn=>{btn.addEventListener("click",()=>setFeaturePaymentStatus(btn.dataset.purchaseId,btn.dataset.approve==="true",btn))})}const FEATURE_STATUS_BADGE={Approved:"status-active","Pending review":"status-pending",Rejected:"status-declined"};function featurePaymentRowHtml(p){const when=p.endsAt&&p.status==="Approved"?" · until "+new Date(p.endsAt).toLocaleDateString():"";const canApprove=p.status==="Pending review"||p.status==="Rejected";const canReject=p.status==="Pending review"||p.status==="Approved";return`\n    <div class="wholesale-row feature-payment-row">\n      <div class="wholesale-row-info">\n        <strong>${escapeHtml(p.storeName||"")}</strong>\n        <span class="status-badge ${FEATURE_STATUS_BADGE[p.status]||"status-hidden"}">${escapeHtml(p.status)}</span>\n        <div class="helper-text">\n          ${escapeHtml(formatMoney(p.amount))} · ref ${escapeHtml(p.reference)} · ${p.days} day${p.days===1?"":"s"}${escapeHtml(when)}\n        </div>\n        <div class="helper-text">${escapeHtml((p.productNames||[]).join(", "))}</div>\n        ${p.ocrNotes?`<div class="helper-text feature-payment-notes">${escapeHtml(p.ocrNotes)}</div>`:""}\n        ${p.screenshotUrl?`<a href="${escapeAttr(p.screenshotUrl)}" target="_blank" rel="noopener">View screenshot</a>`:""}\n      </div>\n      <div class="feature-payment-actions">\n        ${canApprove?`<button type="button" class="btn btn-small btn-primary" data-purchase-id="${escapeAttr(p.purchaseId)}" data-approve="true">Approve</button>`:""}\n        ${canReject?`<button type="button" class="btn btn-small" data-purchase-id="${escapeAttr(p.purchaseId)}" data-approve="false">Reject</button>`:""}\n      </div>\n    </div>\n  `}async function setFeaturePaymentStatus(purchaseId,approve,btn){const errorEl=document.getElementById("feature-payments-error");errorEl.textContent="";if(!approve&&!window.confirm("Reject this payment? If it was approved, the products stop being featured now."))return;btn.disabled=true;const res=await Api.post("setFeaturePurchaseStatus",{token:Auth.getToken(),purchaseId:purchaseId,approve:approve});if(!res.ok){btn.disabled=false;errorEl.textContent=res.error||"Could not update that payment.";return}await loadFeaturePayments()}let adminSearchTimer=null;let adminSearchSeq=0;function initAdminSearch(){const input=document.getElementById("admin-search-input");input.addEventListener("input",()=>{clearTimeout(adminSearchTimer);adminSearchTimer=setTimeout(()=>runAdminSearch(input.value.trim()),300)});document.getElementById("admin-search-results").addEventListener("click",e=>{const btn=e.target.closest("[data-owner-id]");if(btn)loadStoreAnalytics(btn.dataset.ownerId,btn.dataset.productId||"")})}async function runAdminSearch(q){const statusEl=document.getElementById("admin-search-status");const listEl=document.getElementById("admin-search-results");const seq=++adminSearchSeq;if(q.length<2){statusEl.textContent="";listEl.innerHTML="";return}statusEl.textContent="Searching…";const res=await Api.post("adminSearch",{token:Auth.getToken(),q:q});if(seq!==adminSearchSeq)return;if(!res.ok){statusEl.textContent=res.error||"Search failed. Please try again.";listEl.innerHTML="";return}const stores=res.stores||[];const products=res.products||[];statusEl.textContent=stores.length||products.length?"":`Nothing matches "${q}".`;listEl.innerHTML=(stores.length?`<h3>Stores</h3>${stores.map(s=>`\n      <button type="button" class="admin-search-hit" data-owner-id="${escapeAttr(s.ownerId)}">\n        <strong>${escapeHtml(s.storeName)}</strong>\n        <span class="helper-text">${escapeHtml(s.storeSlug)}${s.status!=="active"?" · "+escapeHtml(s.status):""}</span>\n      </button>`).join("")}`:"")+(products.length?`<h3>Products</h3>${products.map(p=>`\n      <button type="button" class="admin-search-hit" data-owner-id="${escapeAttr(p.ownerId)}" data-product-id="${escapeAttr(p.productId)}">\n        <strong>${escapeHtml(p.name)}</strong>\n        <span class="helper-text">${escapeHtml(p.storeName)}${p.status!=="active"?" · "+escapeHtml(p.status):""}</span>\n      </button>`).join("")}`:"")}async function loadStoreAnalytics(ownerId,productId){const el=document.getElementById("admin-analytics");el.classList.remove("hidden");el.innerHTML='<p class="helper-text">Loading store details…</p>';const res=await Api.post("adminStoreAnalytics",{token:Auth.getToken(),ownerId:ownerId});if(!res.ok){el.innerHTML=`<p class="form-error">${escapeHtml(res.error||"Could not load this store.")}</p>`;return}el.innerHTML=storeAnalyticsHtml(res.analytics,productId);const hit=productId&&el.querySelector(".is-picked");(hit||el).scrollIntoView({behavior:"smooth",block:"start"})}function statusCountsHtml(byStatus){const keys=Object.keys(byStatus||{});return keys.length?keys.map(k=>`${escapeHtml(k)} ${byStatus[k]}`).join(" · "):"none yet"}function storeAnalyticsHtml(a,pickedProductId){const s=a.store;const joined=s.createdAt?new Date(s.createdAt).toLocaleDateString():"";const phoneHref=String(s.phone||"").replace(/[^0-9+]/g,"");const type=s.storeType==="retailer"?"Retailer":`${s.storeType==="distributor"?"Distributor":"Wholesaler"}${s.wholesaleVerified?" (verified)":" (call pending)"}`;const stat=(label,value)=>`<div class="admin-stat"><span class="admin-stat-value">${value}</span><span class="admin-stat-label">${label}</span></div>`;const rows=a.products.map(p=>`\n    <tr class="${p.productId===pickedProductId?"is-picked":""}">\n      <td>${escapeHtml(p.name)}${p.status!=="active"?` <span class="helper-text">(${escapeHtml(p.status)})</span>`:""}</td>\n      <td>${p.minPrice==null?"-":escapeHtml(formatMoney(p.minPrice))}</td>\n      <td>${p.stock==null?"-":p.stock}</td>\n      <td>${p.views}</td>\n    </tr>`).join("");const featuring=a.featuring.recent.map(f=>`\n    <li>${escapeHtml(f.reference)} · ${escapeHtml(f.status)} · ${escapeHtml(formatMoney(f.amount))} for ${f.days} day${f.days===1?"":"s"}${f.endsAt?" · ends "+escapeHtml(new Date(f.endsAt).toLocaleDateString()):""}</li>`).join("");return`\n    <div class="admin-analytics-head">\n      <h3>${escapeHtml(s.storeName)}</h3>\n      <a href="../store.html?store=${encodeURIComponent(s.storeSlug)}" target="_blank" rel="noopener">View store</a>\n    </div>\n    <p class="helper-text">\n      ${escapeHtml(type)} · ${escapeHtml(s.status)}${s.adminFeatured?" · featured by admin":""}${joined?" · joined "+escapeHtml(joined):""}<br>\n      ${s.phone?`<a href="tel:${escapeAttr(phoneHref)}">${escapeHtml(s.phone)}</a> · `:""}${s.email?`<a href="mailto:${escapeAttr(s.email)}">${escapeHtml(s.email)}</a> · `:""}${escapeHtml([s.village,s.island].filter(Boolean).join(", "))}\n    </p>\n    <div class="admin-stats">\n      ${stat("store visits",s.visits)}\n      ${stat("product views",a.totals.views)}\n      ${stat("orders",a.orders.count)}\n      ${stat("sales (paid)",escapeHtml(formatMoney(a.orders.sales)))}\n      ${stat("bookings",a.bookings.count)}\n      ${stat("rating",a.reviews.average==null?"-":a.reviews.average+" ★ ("+a.reviews.count+")")}\n      ${stat("featuring spend",escapeHtml(formatMoney(a.featuring.spent)))}\n    </div>\n    <p class="helper-text"><strong>Orders:</strong> ${statusCountsHtml(a.orders.byStatus)}<br>\n      <strong>Bookings:</strong> ${statusCountsHtml(a.bookings.byStatus)}</p>\n    <h4>Products (${a.totals.activeProducts} active of ${a.totals.products}), most viewed first</h4>\n    ${a.products.length?`<div class="admin-table-wrap"><table class="admin-table">\n      <thead><tr><th>Product</th><th>From</th><th>Stock</th><th>Views</th></tr></thead>\n      <tbody>${rows}</tbody></table></div>`:'<p class="helper-text">No products yet.</p>'}\n    <h4>Paid featuring${a.featuring.activeNow?' <span class="status-badge status-active">featured now</span>':""}</h4>\n    ${featuring?`<ul class="admin-featuring-list">${featuring}</ul>`:'<p class="helper-text">No featuring purchases.</p>'}\n  `}